#include <stdio.h>
#include <unistd.h>
#include <sys/wait.h>

int main(void)
{
    pid_t pid = fork();

    if (pid == 0) {
        printf("child: pid=%d\n", getpid());
        _exit(0);
    } else if (pid > 0) {
        int status;
        waitpid(pid, &status, 0);
        printf("parent: child %d exited\n", pid);
    } else {
        perror("fork");
        return 1;
    }
    return 0;
}

